//! WASM conformance: the same fixtures as the native suite, replayed
//! through the exported bindings. Fixture table is generated by
//! build.rs from `contracts/fixtures/` (include_str! — no fs at runtime).

mod fixtures {
    include!(concat!(env!("OUT_DIR"), "/fixtures.rs"));
}

use fixtures::Fixture;
use prism_core::settings::Settings;
use serde_json::Value;
use wasm_bindgen_test::wasm_bindgen_test;

fn collect_events(json: &str, acc: &mut Vec<Value>) -> Result<(), String> {
    let parsed: Value =
        serde_json::from_str(json).map_err(|e| format!("invalid event JSON: {e}"))?;
    match parsed {
        Value::Array(items) => acc.extend(items),
        _ => return Err("event output is not an array".into()),
    }
    Ok(())
}

fn decode_sse(input: &str, byte_split: bool) -> Result<Value, String> {
    let mut d = prism_wasm::SseDecoder::new();
    let mut acc: Vec<Value> = Vec::new();
    if byte_split {
        for b in input.as_bytes() {
            collect_events(&d.feed(std::slice::from_ref(b)), &mut acc)?;
        }
    } else {
        collect_events(&d.feed(input.as_bytes()), &mut acc)?;
    }
    collect_events(&d.finish(), &mut acc)?;
    Ok(Value::Array(acc))
}

fn decode_ndjson(input: &str, byte_split: bool) -> Result<Value, String> {
    let mut d = prism_wasm::NdjsonDecoder::new();
    let mut acc: Vec<Value> = Vec::new();
    if byte_split {
        for b in input.as_bytes() {
            collect_events(&d.feed(std::slice::from_ref(b)), &mut acc)?;
        }
    } else {
        collect_events(&d.feed(input.as_bytes()), &mut acc)?;
    }
    collect_events(&d.finish(), &mut acc)?;
    Ok(Value::Array(acc))
}

fn expected_value(f: &Fixture) -> Value {
    serde_json::from_str(f.expected)
        .unwrap_or_else(|e| panic!("{}: bad expected.json: {e}", f.name))
}

#[wasm_bindgen_test]
fn sse_fixtures_decode_identically_whole_and_bytewise() {
    for f in fixtures::SSE {
        let expected = expected_value(f);
        let whole = decode_sse(f.input, false).unwrap_or_else(|e| panic!("{}: {e}", f.name));
        let bytes = decode_sse(f.input, true).unwrap_or_else(|e| panic!("{}: {e}", f.name));
        assert_eq!(whole, expected, "{} whole", f.name);
        assert_eq!(bytes, expected, "{} byte-split", f.name);
    }
}

#[wasm_bindgen_test]
fn ollama_fixtures_decode_identically_whole_and_bytewise() {
    for f in fixtures::OLLAMA {
        let expected = expected_value(f);
        let whole = decode_ndjson(f.input, false).unwrap_or_else(|e| panic!("{}: {e}", f.name));
        let bytes = decode_ndjson(f.input, true).unwrap_or_else(|e| panic!("{}: {e}", f.name));
        assert_eq!(whole, expected, "{} whole", f.name);
        assert_eq!(bytes, expected, "{} byte-split", f.name);
    }
}

#[wasm_bindgen_test]
fn api_fixtures_parse_to_expected() {
    for f in fixtures::API {
        let actual: Value = serde_json::from_str(&prism_wasm::parse_api_response(f.input)).unwrap();
        assert_eq!(actual, expected_value(f), "{}", f.name);
    }
}

